<template><div class="page"><div class="page-head"><div><h1 class="page-title">用户管理</h1><p class="page-subtitle">账号状态、群聊参与与违规风险</p></div><button class="btn" @click="exportCsv"><Download :size="15"/>导出</button></div><section class="app-card"><div class="filters"><div class="search"><Search :size="15"/><input v-model="q" placeholder="搜索用户名 / 用户 ID" @keyup.enter="load"/></div><select v-model="status" class="select" @change="load"><option value="">全部状态</option><option>online</option><option>offline</option><option>banned</option></select><button class="btn" @click="load">查询</button><StatusBadge :tone="error?'danger':'success'" dot>{{error?'接口异常':`共 ${total} 人`}}</StatusBadge></div><div class="table-wrap"><table class="data-table"><thead><tr><th>用户</th><th>角色</th><th>状态</th><th>群聊</th><th>消息</th><th>违规</th><th>最后活跃</th><th></th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td><div class="user"><span>{{String(u.username||'U').slice(0,1).toUpperCase()}}</span><div><b>{{u.username||`User #${u.id}`}}</b><small>#{{u.id}}</small></div></div></td><td><StatusBadge :tone="u.role==='super_admin'?'primary':'neutral'">{{u.role||'user'}}</StatusBadge></td><td><StatusBadge dot :tone="u.status==='online'?'success':u.status==='banned'?'danger':'neutral'">{{u.status||'offline'}}</StatusBadge></td><td>{{u.rooms??0}}</td><td>{{fmt(u.messages)}}</td><td><b :class="u.violations?'risk':''">{{u.violations??0}}</b></td><td class="muted">{{formatTime(u.last_active)}}</td><td><div class="actions"><button class="btn btn-sm" @click="detail(u)">详情</button><button class="btn btn-sm btn-danger" @click="remove(u)"><Trash2 :size="13"/>删除</button></div></td></tr><tr v-if="!users.length"><td colspan="8" class="empty">{{error||'暂无用户数据'}}</td></tr></tbody></table></div></section><dialog ref="dialog" class="detail-dialog"><div v-if="selected"><header><div><b>{{selected.username||`User #${selected.id}`}}</b><span>#{{selected.id}}</span></div><button class="icon-btn" @click="dialog?.close()">×</button></header><pre>{{JSON.stringify(selected,null,2)}}</pre></div></dialog></div></template>
<script setup>import{onMounted,ref}from'vue';import{Search,Download,Trash2}from'lucide-vue-next';import StatusBadge from'../../components/common/StatusBadge.vue';import{adminApi}from'../../api/admin.js';const users=ref([]),q=ref(''),status=ref(''),error=ref(''),total=ref(0),dialog=ref(),selected=ref(null);const fmt=v=>v==null?'—':new Intl.NumberFormat('zh-CN',{notation:Number(v)>9999?'compact':'standard'}).format(v);const formatTime=v=>v?new Date(v).toLocaleString('zh-CN'):'—';async function load(){error.value='';try{const d=await adminApi.users({q:q.value,status:status.value,page_size:100});users.value=Array.isArray(d)?d:(d?.items||d?.users||[]);total.value=d?.total??users.value.length}catch(e){users.value=[];error.value=e.message}}async function detail(u){try{selected.value=await adminApi.user(u.id)}catch{selected.value=u}dialog.value?.showModal()}async function remove(u){if(!confirm(`确定删除用户 ${u.username||u.id}？该操作不可恢复。`))return;try{await adminApi.deleteUser(u.id);await load()}catch(e){alert(e.message)}}function exportCsv(){const rows=[['id','username','role','status','rooms','messages','violations','last_active'],...users.value.map(u=>[u.id,u.username,u.role,u.status,u.rooms,u.messages,u.violations,u.last_active])];const csv='\ufeff'+rows.map(r=>r.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='lan-im-users.csv';a.click();URL.revokeObjectURL(url)}onMounted(load)</script>
<style scoped>.page{display:grid;gap:16px}.page-head{display:flex;justify-content:space-between;align-items:flex-start}.filters{padding:14px;display:flex;gap:10px;align-items:center;border-bottom:1px solid var(--line)}.search{height:38px;min-width:280px;display:flex;align-items:center;gap:8px;padding:0 11px;border:1px solid var(--line-strong);border-radius:9px;color:var(--text-3)}.search input{border:0;outline:0;background:transparent;color:var(--text);width:100%}.select{width:150px}.user{display:flex;align-items:center;gap:9px}.user>span{width:34px;height:34px;border-radius:10px;background:var(--primary-soft);color:var(--primary);display:grid;place-items:center;font-weight:800}.user b,.user small{display:block}.user small{font-size:10px;color:var(--text-3);margin-top:2px}.actions{display:flex;gap:6px;justify-content:flex-end}.risk{color:var(--danger)}.empty{text-align:center!important;color:var(--text-3);padding:30px!important}.detail-dialog{width:min(620px,90vw);border:1px solid var(--line);border-radius:14px;background:var(--surface);color:var(--text);padding:0;box-shadow:var(--shadow-lg)}.detail-dialog::backdrop{background:rgba(10,18,32,.45)}.detail-dialog header{display:flex;justify-content:space-between;align-items:center;padding:16px 18px;border-bottom:1px solid var(--line)}.detail-dialog header span{display:block;color:var(--text-3);font-size:10px;margin-top:3px}.detail-dialog pre{margin:0;padding:18px;max-height:65vh;overflow:auto;font-size:11px}@media(max-width:720px){.filters{align-items:stretch;flex-direction:column}.search{min-width:0}.select{width:100%}}</style>
